        'text' => SRTextWireframe.fromJson(json),
        'image' => SRImageWireframe.fromJson(json),
        'placeholder' => SRPlaceholderWireframe.fromJson(json),
        'webview' => SRWebviewWireframe.fromJson(json),
        'embedded_content' => SREmbeddedContentWireframe.fromJson(json),
        final other => throw FormatException(
          'Unknown SRWireframe type: '
          '$other',
        ),
      };

  /// Defines the unique ID of the wireframe. This is persistent throughout the
  /// view lifetime.
  int get id;

  /// The position in pixels on X axis of the UI element in absolute
  /// coordinates. The anchor point is always the top-left corner of the
